/**
 * 技能 × 薪资交叉统计：从原始 JD 全文切词得到岗位级技能位掩码。
 *
 * 由 ~/.claude/skills/boss-crawler/assets/jobsmap/skill_salary.py 生成，勿手改。
 *
 * - skillNames：保留的技能名，按全量样本量降序，**数组下标即位序**
 * - skillMeta：技能名 → 分组（语言与框架 / 数据与中间件 / 云与运维 / AI 与算法 / 工程能力）
 * - skillRows：匿名行 [职类, 城市, 经验, 学历, 规模, 领域, 平台, maskLo, maskHi, 低值, 高值]
 *   前 7 位维度索引与 insightRows 完全一致（同一套 cube_rules），
 *   第 8/9 位为技能位掩码（低 30 位 / 高 30 位，合计支持 60 个技能）
 *
 * 使用注意：
 * - 一行 = 一个岗位，同一岗位命中多个技能时会同时在多个位上置 1，
 *   因此各技能样本数之和大于总样本数，不能相加
 * - 「溢价」= 命中该技能的岗位中位薪资 − 当前筛选下全部岗位中位薪资，
 *   是相关性不是因果：高薪岗位本来就倾向要求更多技能
 * - 样本门槛 n>=100，低于该值的技能未进入词典
 */

